import {useState} from 'react';
import {
  Flex,
  Box,
  Text,
  Switch,
  Card,
  TabProvider,
  TabList,
  Tab,
  TabPanel,
  type Theme,
} from '@gravity-ui/uikit';
import {House, CircleInfo, Gear, Sun, Moon} from '@gravity-ui/icons';

import {HomePage} from './pages/HomePage';
import {AboutPage} from './pages/AboutPage';
import {SettingsPage} from './pages/SettingsPage';

interface AppProps {
  theme: Theme;
  onThemeChange: (theme: Theme) => void;
}

export function App({theme, onThemeChange}: AppProps) {
  const [tab, setTab] = useState('home');
  const isDark = theme === 'dark';

  return (
    <Box style={{minHeight: '100vh', background: 'var(--g-color-base-background)'}}>
      {/* Header */}
      <Flex
        alignItems=\"center\"
        justifyContent=\"space-between\"
        style={{
          padding: '0 var(--g-spacing-4)',
          height: 56,
          borderBottom: '1px solid var(--g-color-line-generic)',
          background: 'var(--g-color-base-background)',
        }}
      >
        <Text variant=\"header-1\">My App</Text>
        <Flex alignItems=\"center\" gap={3}>
          <Flex alignItems=\"center\" gap={2}>
            <Box as={Sun} width={16} height={16} color={isDark ? 'var(--g-color-text-hint)' : 'var(--g-color-text-brand)'} />
            <Switch
              checked={isDark}
              onUpdate={(checked) => onThemeChange(checked ? 'dark' : 'light')}
            />
            <Box as={Moon} width={16} height={16} color={isDark ? 'var(--g-color-text-brand)' : 'var(--g-color-text-hint)'} />
          </Flex>
        </Flex>
      </Flex>

      {/* Navigation */}
      <Box style={{padding: 'var(--g-spacing-4) var(--g-spacing-4) 0'}}>
        <TabProvider value={tab} onUpdate={setTab}>
          <TabList>
            <Tab value=\"home\" icon={<House width={16} height={16} />}>
              Home
            </Tab>
            <Tab value=\"about\" icon={<CircleInfo width={16} height={16} />}>
              About
            </Tab>
            <Tab value=\"settings\" icon={<Gear width={16} height={16} />}>
              Settings
            </Tab>
          </TabList>
        </TabProvider>
      </Box>

      {/* Pages */}
      <Box style={{padding: 'var(--g-spacing-4)'}}>
        <TabProvider value={tab} onUpdate={setTab}>
          <TabPanel value=\"home\">
            <HomePage />
          </TabPanel>
          <TabPanel value=\"about\">
            <AboutPage />
          </TabPanel>
          <TabPanel value=\"settings\">
            <SettingsPage isDark={isDark} theme={theme} />
          </TabPanel>
        </TabProvider>
      </Box>
    </Box>
  );
}
EOF"

