import {Card, Flex, Text, Switch, Icon} from '@gravity-ui/uikit';
import type {Theme} from '@gravity-ui/uikit';
import {Sun, Moon} from '@gravity-ui/icons';

interface SettingsPageProps {
  theme: Theme;
}

